insert into roadmap_phases ("order", title, summary, est_weeks, checkpoint, learn) values (1, 'Phase 0 — Language & Foundations', 'Get fluent enough in one language (C++ here) to stop fighting syntax. Learn I/O, variables, control flow, functions, arrays, and your language''s collection toolkit (the STL in C++). Do lots of pattern-printing to make loops and nesting automatic.', '1-2 weeks', 'You can write, compile, and debug a 40-line program without looking up basic syntax.', '["Setup & fast I/O","Types, operators, control flow","Functions & scope","Arrays & vectors","Core STL: vector, pair, string","Pattern printing (nested loops)"]') on conflict ("order") do update set title = excluded.title, summary = excluded.summary, est_weeks = excluded.est_weeks, checkpoint = excluded.checkpoint, learn = excluded.learn;
insert into roadmap_phases ("order", title, summary, est_weeks, checkpoint, learn) values (2, 'Phase 1 — Core Linear Structures', 'The bread-and-butter of interviews. Arrays, binary search, strings, and the STL containers. Master the fundamental patterns here — two pointers, sliding window, prefix sums — because they reappear everywhere.', '3-4 weeks', 'You can recognize when a problem is a sliding-window or two-pointer problem without being told.', '["Arrays & 2D arrays","Binary search (+ on answer)","Strings & string algorithms","STL containers: map, set, unordered_*","Patterns: two pointers, sliding window, prefix sum"]') on conflict ("order") do update set title = excluded.title, summary = excluded.summary, est_weeks = excluded.est_weeks, checkpoint = excluded.checkpoint, learn = excluded.learn;
insert into roadmap_phases ("order", title, summary, est_weeks, checkpoint, learn) values (3, 'Phase 2 — Recursion & Sorting', 'Recursion is the conceptual gateway to trees, backtracking, and DP. Get comfortable drawing recursion trees. Then learn the classic sorts and divide-and-conquer thinking.', '2-3 weeks', 'You can write a backtracking solution from the template without copying one.', '["Recursion fundamentals & recursion trees","Subsets, permutations, combinations","Backtracking template (N-Queens, Sudoku)","Merge sort, quick sort","Divide & conquer"]') on conflict ("order") do update set title = excluded.title, summary = excluded.summary, est_weeks = excluded.est_weeks, checkpoint = excluded.checkpoint, learn = excluded.learn;
insert into roadmap_phases ("order", title, summary, est_weeks, checkpoint, learn) values (4, 'Phase 3 — Pointer & LIFO/FIFO Structures', 'Linked lists teach pointer manipulation; stacks and queues teach a whole family of patterns (monotonic stack, next-greater-element). These show up constantly in interviews.', '2-3 weeks', 'You can reverse a linked list and detect a cycle without reference.', '["Linked lists (singly, doubly, circular)","Fast-slow pointers (Floyd''s cycle)","Stacks & queues","Monotonic stack","Deque patterns"]') on conflict ("order") do update set title = excluded.title, summary = excluded.summary, est_weeks = excluded.est_weeks, checkpoint = excluded.checkpoint, learn = excluded.learn;
