insert into roadmap_phases ("order", title, summary, est_weeks, checkpoint, learn) values (6, 'Phase 5 — Graphs & Greedy', 'Graphs generalize trees. Learn representation, BFS/DFS, cycle detection, topological sort, and shortest paths. Greedy is a mindset — prove the local choice is safe.', '3-4 weeks', 'You can model a word/grid problem as a graph and pick the right traversal.', '["Graph representation, BFS, DFS","Cycle detection (directed/undirected)","Topological sort","Shortest paths (Dijkstra, Bellman-Ford)","MST & union-find","Greedy strategies"]') on conflict ("order") do update set title = excluded.title, summary = excluded.summary, est_weeks = excluded.est_weeks, checkpoint = excluded.checkpoint, learn = excluded.learn;
