insert into code_snippets (topic_id, language_id, label, code) select t.id, l.id, 'Universal backtracking template', 'void backtrack(State& s, vector<Solution>& out) {
    if (isGoal(s)) { out.push_back(extract(s)); return; }
    for (auto& choice : choices(s)) {
        apply(s, choice);        // try
        backtrack(s, out);       // recurse
        undo(s, choice);         // un-try
    }
}' from topics t, languages l where t.slug = 'backtracking' and l.code = 'cpp' on conflict (topic_id, language_id, label) do update set code = excluded.code;
insert into code_snippets (topic_id, language_id, label, code) select t.id, l.id, 'N-Queens — safety check + placement', 'bool safe(vector<int>& col, int r, int c) {
    for (int i = 0; i < r; i++)
        if (col[i] == c || abs(col[i]-c) == abs(i-r)) return false;
    return true;
}
void solve(int r, int n, vector<int>& col, int& count) {
    if (r == n) { count++; return; }
    for (int c = 0; c < n; c++)
        if (safe(col, r, c)) {
            col[r] = c;          // place
            solve(r+1, n, col, count);
            col[r] = -1;         // remove (backtrack)
        }
}' from topics t, languages l where t.slug = 'backtracking' and l.code = 'cpp' on conflict (topic_id, language_id, label) do update set code = excluded.code;
insert into code_snippets (topic_id, language_id, label, code) select t.id, l.id, 'Merge sort', 'void merge(vector<int>& a, int l, int m, int r) {
    vector<int> tmp;
    int i = l, j = m + 1;
    while (i <= m && j <= r)
        tmp.push_back(a[i] <= a[j] ? a[i++] : a[j++]);
    while (i <= m) tmp.push_back(a[i++]);
    while (j <= r) tmp.push_back(a[j++]);
    for (int k = 0; k < (int)tmp.size(); k++) a[l + k] = tmp[k];
}
void mergeSort(vector<int>& a, int l, int r) {
    if (l >= r) return;
    int m = l + (r - l) / 2;
    mergeSort(a, l, m); mergeSort(a, m + 1, r);
    merge(a, l, m, r);
}' from topics t, languages l where t.slug = 'sorting' and l.code = 'cpp' on conflict (topic_id, language_id, label) do update set code = excluded.code;
insert into code_snippets (topic_id, language_id, label, code) select t.id, l.id, 'Quickselect — k-th smallest, O(n) avg', 'int partition(vector<int>& a, int l, int r) {
    int pivot = a[r], i = l;
    for (int j = l; j < r; j++)
        if (a[j] < pivot) swap(a[i++], a[j]);
    swap(a[i], a[r]);
    return i;
}
int quickselect(vector<int>& a, int l, int r, int k) {
    int p = partition(a, l, r);
    if (p == k) return a[p];
    return p < k ? quickselect(a, p+1, r, k)
                 : quickselect(a, l, p-1, k);
}' from topics t, languages l where t.slug = 'sorting' and l.code = 'cpp' on conflict (topic_id, language_id, label) do update set code = excluded.code;
