insert into code_snippets (topic_id, language_id, label, code) select t.id, l.id, 'Iterative reversal', 'ListNode* reverse(ListNode* head) {
    ListNode* prev = nullptr;
    while (head) {
        ListNode* next = head->next;
        head->next = prev;   // rewire
        prev = head;
        head = next;
    }
    return prev;             // new head
