insert into code_snippets (topic_id, language_id, label, code) select t.id, l.id, 'Search & insert', 'TreeNode* insert(TreeNode* root, int val) {
    if (!root) return new TreeNode(val);
    if (val < root->val) root->left = insert(root->left, val);
    else root->right = insert(root->right, val);
    return root;
}
bool search(TreeNode* root, int val) {
    while (root) {
        if (root->val == val) return true;
        root = val < root->val ? root->left : root->right;
    }
    return false;
}' from topics t, languages l where t.slug = 'bst' and l.code = 'cpp' on conflict (topic_id, language_id, label) do update set code = excluded.code;
