insert into code_snippets (topic_id, language_id, label, code) select t.id, l.id, 'Complement lookup — Two Sum', 'vector<int> twoSum(vector<int>& nums, int target) {
    unordered_map<int,int> seen;   // value -> index
    for (int i = 0; i < (int)nums.size(); i++) {
        int need = target - nums[i];
        if (seen.count(need)) return {seen[need], i};
        seen[nums[i]] = i;
    }
    return {};
}' from topics t, languages l where t.slug = 'hashing' and l.code = 'cpp' on conflict (topic_id, language_id, label) do update set code = excluded.code;
