insert into code_snippets (topic_id, language_id, label, code) select t.id, l.id, 'Topological sort (Kahn''s, BFS)', 'vector<int> topoSort(int n, vector<vector<int>>& adj) {
    vector<int> indeg(n, 0), order;
    for (int u = 0; u < n; u++)
        for (int v : adj[u]) indeg[v]++;
    queue<int> q;
    for (int i = 0; i < n; i++) if (!indeg[i]) q.push(i);
    while (!q.empty()) {
        int u = q.front(); q.pop(); order.push_back(u);
        for (int v : adj[u]) if (--indeg[v] == 0) q.push(v);
    }
    return order;   // size < n means a cycle exists
}' from topics t, languages l where t.slug = 'graphs' and l.code = 'cpp' on conflict (topic_id, language_id, label) do update set code = excluded.code;
insert into code_snippets (topic_id, language_id, label, code) select t.id, l.id, 'Dijkstra — shortest path (min-heap)', 'vector<int> dijkstra(int src, vector<vector<pair<int,int>>>& adj) {
    int n = adj.size();
    vector<int> dist(n, INT_MAX); dist[src] = 0;
    priority_queue<pair<int,int>, vector<pair<int,int>>,
                   greater<>> pq;
    pq.push({0, src});
    while (!pq.empty()) {
        auto [d, u] = pq.top(); pq.pop();
        if (d > dist[u]) continue;
        for (auto [v, w] : adj[u])
            if (dist[u] + w < dist[v]) {
                dist[v] = dist[u] + w;
                pq.push({dist[v], v});
            }
    }
    return dist;
}' from topics t, languages l where t.slug = 'graphs' and l.code = 'cpp' on conflict (topic_id, language_id, label) do update set code = excluded.code;
insert into code_snippets (topic_id, language_id, label, code) select t.id, l.id, 'Recursion → memoization (top-down)', 'int rob(vector<int>& nums, int i, vector<int>& memo) {
    if (i >= (int)nums.size()) return 0;
    if (memo[i] != -1) return memo[i];
    int take = nums[i] + rob(nums, i + 2, memo);
    int skip = rob(nums, i + 1, memo);
    return memo[i] = max(take, skip);
}' from topics t, languages l where t.slug = 'dynamic-programming' and l.code = 'cpp' on conflict (topic_id, language_id, label) do update set code = excluded.code;
insert into code_snippets (topic_id, language_id, label, code) select t.id, l.id, 'Tabulation (bottom-up) + O(1) space', 'int rob(vector<int>& nums) {
    int prev2 = 0, prev1 = 0;
    for (int x : nums) {
        int cur = max(prev1, prev2 + x);
        prev2 = prev1;
        prev1 = cur;
    }
    return prev1;
}' from topics t, languages l where t.slug = 'dynamic-programming' and l.code = 'cpp' on conflict (topic_id, language_id, label) do update set code = excluded.code;
insert into code_snippets (topic_id, language_id, label, code) select t.id, l.id, 'LCS — classic 2D table', 'int lcs(string a, string b) {
    int n = a.size(), m = b.size();
    vector<vector<int>> dp(n+1, vector<int>(m+1, 0));
    for (int i = 1; i <= n; i++)
        for (int j = 1; j <= m; j++)
            dp[i][j] = (a[i-1] == b[j-1])
                ? dp[i-1][j-1] + 1
                : max(dp[i-1][j], dp[i][j-1]);
    return dp[n][m];
}' from topics t, languages l where t.slug = 'dynamic-programming' and l.code = 'cpp' on conflict (topic_id, language_id, label) do update set code = excluded.code;
insert into code_snippets (topic_id, language_id, label, code) select t.id, l.id, 'Trie node + insert/search', 'struct TrieNode {
    TrieNode* child[26] = {};
    bool isEnd = false;
};
struct Trie {
    TrieNode* root = new TrieNode();
    void insert(const string& w) {
        TrieNode* cur = root;
        for (char c : w) {
            int i = c - ''a'';
            if (!cur->child[i]) cur->child[i] = new TrieNode();
            cur = cur->child[i];
        }
        cur->isEnd = true;
    }
    bool search(const string& w) {
        TrieNode* cur = root;
        for (char c : w) {
            int i = c - ''a'';
            if (!cur->child[i]) return false;
            cur = cur->child[i];
        }
        return cur->isEnd;
    }
};' from topics t, languages l where t.slug = 'tries' and l.code = 'cpp' on conflict (topic_id, language_id, label) do update set code = excluded.code;
